#include <stdio.h>

int main(void)
{
    FILE *input = fopen("input/reading.txt", "rb");
    if (input == NULL) {
        puts("open-error");
        return 1;
    }
    if (fclose(input) == EOF) {
        puts("close-error");
        return 1;
    }
    puts("opened");
    return 0;
}

